package com.cvns.controller;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import com.cvns.dtos.RequestDtos.ChatRequest;import com.cvns.dtos.ResponseDtos.ApiResponse;import com.cvns.service.ChatbotService;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;
@RestController @RequestMapping("/chatbot") @RequiredArgsConstructor public class ChatbotController{private final ChatbotService s;@PostMapping public ResponseEntity<?> ask(@RequestBody @Valid ChatRequest r){return ResponseEntity.ok(ApiResponse.success("Chatbot response",s.ask(r.message())));}}
